import { Test } from '@nestjs/testing';
import {
  FastifyAdapter,
  type NestFastifyApplication,
} from '@nestjs/platform-fastify';
import { ConfigService } from '@nestjs/config';
import { Interface, type JsonFragment } from 'ethers';
import {
  CYBER_DAO_GOVERNANCE_READ_ABI,
  CYBER_DAO_GOVERNANCE_WRITE_ABI,
} from '@dao-platform/blockchain-cyberchain';
import { BlockchainVerificationService } from '../blockchain-verification.service';
import { BlockchainVerificationController } from '../blockchain-verification.controller';

const contract = '0x' + '11'.repeat(20),
  creator = '0x' + '22'.repeat(20),
  hash = '0x' + '33'.repeat(32),
  blockHash = '0x' + '44'.repeat(32),
  metadata = '0x' + '55'.repeat(32);
const abi = new Interface([
  ...(CYBER_DAO_GOVERNANCE_WRITE_ABI as unknown as JsonFragment[]),
  ...CYBER_DAO_GOVERNANCE_READ_ABI,
]);
const p = {
  id: 'p',
  dao_id: 'dao',
  on_chain_id: '28',
  chain_id: '1212',
  contract_address: contract,
  starts_at: new Date(1000 * 1000),
  ends_at: new Date(2000 * 1000),
  status: 'VOTING_CLOSED',
  metadata_hash: metadata,
  metadata_uri: 'ipfs://verified',
  finalized_at: null,
  total_votes: '0',
};
const config = new ConfigService({
  CYBERCHAIN_CHAIN_ID: '1212',
  GOVERNANCE_CONTRACT_ADDRESS: contract,
  GOVERNANCE_DEPLOYMENT_BLOCK: '1',
  AI_SERVER_TOKEN: 'test-operator-token',
});
function fixture(
  overrides: Record<string, unknown> = {},
  hasStoredEvent = true,
  checkpoint: unknown = {
    processed_block_number: '100',
    processed_block_hash: blockHash,
  },
) {
  const encoded = abi.encodeEventLog(abi.getEvent('ProposalCreated')!, [
    '28',
    creator,
    0,
    metadata,
    'ipfs://verified',
    2,
    1000,
    2000,
  ]);
  const args = {
    proposalId: '28',
    creator,
    proposalType: '0',
    metadataHash: metadata,
    metadataURI: 'ipfs://verified',
    optionCount: '2',
    startsAt: '1000',
    endsAt: '2000',
  };
  const stored = {
    event_name: 'ProposalCreated',
    evidence_id: 'e1',
    transaction_hash: hash,
    log_index: '0',
    block_number: '1',
    block_hash: blockHash,
    event_args: args,
  };
  const db = {
    selectFrom: jest.fn((table: string) => {
      const q: any = {
        selectAll: () => q,
        where: jest.fn(() => q),
        executeTakeFirst: async () =>
          table === 'indexer_checkpoints' ? checkpoint : { ...p, ...overrides },
        execute: async () =>
          table === 'votes' ||
          (table === 'governance_events' && !hasStoredEvent)
            ? []
            : [stored],
      };
      return q;
    }),
  };
  const service = new BlockchainVerificationService(
    { database: db } as any,
    config,
  );
  const rpc = jest
    .spyOn(service as any, 'rpc')
    .mockImplementation(async (...a: any[]) => {
      const [method, params] = a;
      if (method === 'eth_chainId') return '0x4bc';
      if (method === 'eth_blockNumber') return '0x64';
      if (method === 'eth_getBlockByNumber')
        return { hash: blockHash, number: '0x64', timestamp: '0xbb8' };
      if (method === 'eth_getLogs')
        return [
          {
            ...encoded,
            transactionHash: hash,
            logIndex: '0x0',
            blockNumber: '0x1',
            blockHash,
          },
        ];
      if (method === 'eth_getTransactionReceipt')
        return { status: '0x1', to: contract, blockNumber: '0x1', blockHash };
      if (method === 'eth_getTransactionByHash')
        return { to: contract, from: creator };
      if (method === 'eth_call') {
        const parsed = abi.parseTransaction({ data: params[0].data })!;
        const values =
          parsed.name === 'getProposal'
            ? [
                [
                  metadata,
                  'ipfs://verified',
                  1000,
                  2000,
                  2,
                  0,
                  1,
                  0,
                  0,
                  false,
                  false,
                  false,
                ],
              ]
            : parsed.name === 'proposalState'
              ? [2]
              : [0];
        return abi.encodeFunctionResult(parsed.name, values);
      }
      throw new Error('Unexpected RPC method ' + method);
    });
  return { service, rpc, db };
}
describe('Read-only blockchain verification', () => {
  it('leaves an unknown SQL status unverified rather than inventing a mismatch', async () => {
    const { service } = fixture({ status: 'UNKNOWN' });
    const result = await service.verify('p');
    expect(
      result.comparisons.find((c) => c.field === 'voting_status'),
    ).toMatchObject({ status: 'unverified', database: 'UNKNOWN' });
    expect(result.status).toBe('unverified');
  });
  it('does not compare missing event totals beyond a lagging checkpoint', async () => {
    const { service } = fixture({}, false, {
      processed_block_number: '0',
      processed_block_hash: null,
    });
    const result = await service.verify('p');
    expect(result.status).toBe('unverified');
    expect(
      result.comparisons.some(
        (c) =>
          c.field === 'governance_events.count' && c.status === 'mismatched',
      ),
    ).toBe(false);
  });

  it.each([
    ['DRAFT', 'unverified'],
    ['PENDING', 'unverified'],
    ['PENDING_ON_CHAIN', 'unverified'],
    ['ACTIVE', 'verified'],
    ['VOTING_OPEN', 'verified'],
    ['VOTING_CLOSED', 'verified'],
    ['CLOSED', 'verified'],
    ['FINALIZED', 'verified'],
    ['CANCELLED', 'verified'],
    ['FAILED', 'unverified'],
    ['EXECUTED', 'unverified'],
    ['toString', 'unverified'],
  ])('handles database status %s explicitly', async (status, expected) => {
    const { service, rpc } = fixture({ status });
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) => {
      if (
        status === 'CANCELLED' &&
        args[0] === 'eth_call' &&
        abi.parseTransaction({ data: args[1][0].data })?.name ===
          'proposalState'
      )
        return abi.encodeFunctionResult('proposalState', [3]);
      return original(...args);
    });
    expect(
      (await service.verify('p')).comparisons.find(
        (c) => c.field === 'voting_status',
      )?.status,
    ).toBe(expected);
  });
  it.each([
    [999, 0],
    [1000, 1],
    [1999, 1],
    [2000, 2],
  ])('uses pinned clock %s for stored ACTIVE', async (clock, state) => {
    const { service, rpc } = fixture({ status: 'ACTIVE' });
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) => {
      if (args[0] === 'eth_getBlockByNumber')
        return {
          hash: blockHash,
          number: '0x64',
          timestamp: '0x' + clock.toString(16),
        };
      if (
        args[0] === 'eth_call' &&
        abi.parseTransaction({ data: args[1][0].data })?.name ===
          'proposalState'
      )
        return abi.encodeFunctionResult('proposalState', [state]);
      return original(...args);
    });
    expect(
      (await service.verify('p')).comparisons.find(
        (c) => c.field === 'voting_status',
      )?.status,
    ).toBe('verified');
  });
  it('retains a genuine state mismatch', async () => {
    const { service } = fixture({ status: 'CANCELLED' });
    const result = await service.verify('p');
    expect(result.status).toBe('mismatched');
    expect(
      result.comparisons.find((c) => c.field === 'voting_status')?.status,
    ).toBe('mismatched');
  });
  it.each([
    [null, 'missing'],
    [{ processed_block_number: '99', processed_block_hash: null }, 'lagging'],
    [
      { processed_block_number: '100', processed_block_hash: blockHash },
      'current',
    ],
    [{ processed_block_number: '101', processed_block_hash: null }, 'ahead'],
    [{ processed_block_number: '-1', processed_block_hash: null }, 'invalid'],
    [{ processed_block_number: '1.5', processed_block_hash: null }, 'invalid'],
    [
      { processed_block_number: 'garbage', processed_block_hash: null },
      'invalid',
    ],
    [
      {
        processed_block_number: '100',
        processed_block_hash: '0x' + '99'.repeat(32),
      },
      'invalid',
    ],
  ])('reports checkpoint %j as %s', async (checkpoint, expected) => {
    const { service, db } = fixture({}, true, checkpoint);
    const result = await service.verify('p');
    expect(result.indexer_checkpoint?.status).toBe(expected);
    expect(result.status).toBe(
      expected === 'current' ? 'verified' : 'unverified',
    );
    const query = db.selectFrom.mock.results[1].value;
    expect(query.where).toHaveBeenCalledWith('chain_id', '=', '1212');
    expect(query.where).toHaveBeenCalledWith('contract_address', '=', contract);
    expect(query.where).toHaveBeenCalledWith(
      'indexer_name',
      '=',
      'governance-full',
    );
    expect(query.where).toHaveBeenCalledWith('indexer_version', '=', '1');
  });
  it('does not suppress genuine excess SQL assignments when checkpoint lags', async () => {
    const { service, rpc } = fixture({}, true, {
      processed_block_number: '99',
      processed_block_hash: null,
    });
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) => {
      const response = await original(...args);
      if (
        args[0] !== 'eth_call' ||
        abi.parseTransaction({ data: args[1][0].data })?.name !== 'getProposal'
      )
        return response;
      const data = abi
        .decodeFunctionResult('getProposal', response)[0]
        .toArray();
      data[6] = 0;
      return abi.encodeFunctionResult('getProposal', [data]);
    });
    expect((await service.verify('p')).status).toBe('mismatched');
  });
  it('labels only an exactly event-explained count deficit as indexing lag', async () => {
    const { service, rpc } = fixture({}, true, {
      processed_block_number: '99',
      processed_block_hash: null,
    });
    const original = rpc.getMockImplementation()!;
    const vote = abi.encodeEventLog(abi.getEvent('VoteCast')!, [
      '28',
      creator,
      0,
    ]);
    rpc.mockImplementation(async (...args: any[]) => {
      const response = await original(...args);
      if (args[0] === 'eth_getLogs')
        return [
          ...response,
          {
            ...vote,
            transactionHash: hash,
            logIndex: '0x1',
            blockNumber: '0x64',
            blockHash,
          },
        ];
      if (args[0] !== 'eth_call') return response;
      const name = abi.parseTransaction({ data: args[1][0].data })?.name;
      if (name === 'getProposal') {
        const data = abi.decodeFunctionResult(name, response)[0].toArray();
        data[7] = 1;
        return abi.encodeFunctionResult(name, [data]);
      }
      if (name === 'optionVoteCount')
        return abi.encodeFunctionResult(name, [
          Number(abi.parseTransaction({ data: args[1][0].data })!.args[1]) === 0
            ? 1
            : 0,
        ]);
      return response;
    });
    const result = await service.verify('p');
    expect(result.status).toBe('unverified');
    for (const field of [
      'public.votes.count',
      'public.proposals.total_votes',
      'option_0_vote_count',
    ]) {
      expect(result.comparisons.find((c) => c.field === field)).toMatchObject({
        status: 'unverified',
        reason: expect.stringContaining('Exact count difference'),
      });
    }
  });
  it('marks a missing indexed event mismatched within current checkpoint coverage', async () => {
    const { service } = fixture({}, false);
    expect((await service.verify('p')).status).toBe('mismatched');
  });
  it.each(['timeout', 'missing', 'partial', 'wrong-height', 'checkpoint-rpc'])(
    'handles %s RPC failure without claiming verification',
    async (mode) => {
      const { service, rpc } = fixture(
        {},
        true,
        mode === 'checkpoint-rpc'
          ? { processed_block_number: '99', processed_block_hash: blockHash }
          : undefined,
      );
      const original = rpc.getMockImplementation()!;
      rpc.mockImplementation(async (...args: any[]) => {
        if (mode === 'timeout') throw new Error('RPC timeout');
        if (
          mode === 'checkpoint-rpc' &&
          args[0] === 'eth_getBlockByNumber' &&
          args[1][0] !== '0x64'
        )
          throw new Error('RPC timeout');
        if (mode === 'wrong-height' && args[0] === 'eth_getBlockByNumber')
          return { hash: blockHash, number: '0x63' };
        if (
          args[0] === 'eth_call' &&
          (mode === 'missing' || mode === 'partial')
        )
          return mode === 'missing' ? null : '0x00';
        return original(...args);
      });
      const result = await service.verify('p');
      expect(result.status).toBe(
        mode === 'checkpoint-rpc' ? 'unverified' : 'unavailable',
      );
      if (mode === 'checkpoint-rpc')
        expect(result.indexer_checkpoint?.status).toBe('unavailable');
    },
  );
  it('rejects a reverted transaction receipt as mismatched', async () => {
    const { service, rpc } = fixture();
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) =>
      args[0] === 'eth_getTransactionReceipt'
        ? { status: '0x0', to: contract, blockNumber: '0x1', blockHash }
        : original(...args),
    );
    const result = await service.verify('p');
    expect(result.status).toBe('mismatched');
    expect(result.transactions[0].status).toBe('mismatched');
  });
  it('shows a chain-only event with its evidence without assuming why it is missing from the database', async () => {
    const { service } = fixture({}, false, null);
    const result = await service.verify('p', 'dao');
    expect(result.comparisons).toContainEqual(
      expect.objectContaining({
        field: `governance_event:${hash}:0`,
        database: null,
        blockchain: expect.objectContaining({
          name: 'ProposalCreated',
          transaction_hash: hash,
        }),
        status: 'unverified',
      }),
    );
  });

  it('pins a block, reuses the deployed ABI and verifies proposal, votes, events and receipts', async () => {
    const { service, rpc } = fixture(),
      result = await service.verify('p', 'dao');
    expect(result.status).toBe('verified');
    expect(result.block_number).toBe('100');
    expect(result.events).toHaveLength(1);
    expect(result.transactions[0].status).toBe('verified');
    expect(result.comparisons.every((c) => c.status === 'verified')).toBe(true);
    expect(
      rpc.mock.calls
        .filter((c) => c[0] === 'eth_call')
        .every((c) => (c[1] as any[])[1] === '0x64'),
    ).toBe(true);
    expect(rpc.mock.calls.every((c) => !String(c[0]).includes('send'))).toBe(
      true,
    );
  });
  it('reports database mismatches rather than altering data', async () => {
    const { service } = fixture({ metadata_hash: '0x' + '66'.repeat(32) });
    const result = await service.verify('p');
    expect(result.status).toBe('mismatched');
    expect(
      result.comparisons.find((c) => c.field === 'metadata_hash')?.status,
    ).toBe('mismatched');
  });
  it('maps finalized records to closed while independently checking finalization', async () => {
    const { service, rpc } = fixture({
      status: 'FINALIZED',
      finalized_at: new Date(2000 * 1000),
      winning_option: '0',
      tied: false,
    });
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) => {
      const [method, params] = args;
      const response = await original(...args);
      if (method !== 'eth_call') return response;
      const call = abi.parseTransaction({ data: params[0].data });
      if (call?.name !== 'getProposal') return response;
      const proposal = abi
        .decodeFunctionResult('getProposal', response)[0]
        .toArray();
      proposal[10] = true;
      return abi.encodeFunctionResult('getProposal', [proposal]);
    });
    const result = await service.verify('p');
    expect(result.status).toBe('verified');
    expect(
      result.comparisons.find((c) => c.field === 'voting_status'),
    ).toMatchObject({
      database: 'Closed',
      blockchain: 'Closed',
      status: 'verified',
    });
    expect(
      result.comparisons.find((c) => c.field === 'finalized'),
    ).toMatchObject({
      database: true,
      blockchain: true,
      status: 'verified',
    });
  });
  it('reports RPC failure without fabricated blockchain facts', async () => {
    const { service, rpc } = fixture();
    rpc.mockRejectedValue(new Error('RPC down'));
    const result = await service.verify('p');
    expect(result.status).toBe('unavailable');
    expect(result.proposal).toBeUndefined();
  });
  it('does not verify unpublished proposals', async () => {
    const { service, rpc } = fixture({ on_chain_id: null });
    expect((await service.verify('p')).status).toBe('unverified');
    expect(rpc).not.toHaveBeenCalled();
  });
  it('rejects an unauthorized DAO before any RPC access', async () => {
    const { service, rpc } = fixture();
    await expect(service.verify('p', 'other-dao')).rejects.toThrow('outside');
    expect(rpc).not.toHaveBeenCalled();
  });
  it('detects chain reorganization and withdraws verification', async () => {
    const { service, rpc } = fixture();
    const original = rpc.getMockImplementation()!;
    let blocks = 0;
    rpc.mockImplementation(async (...args: any[]) =>
      args[0] === 'eth_getBlockByNumber' && ++blocks > 1
        ? { hash: '0x' + '77'.repeat(32) }
        : original(...args),
    );
    const result = await service.verify('p');
    expect(result.status).toBe('unverified');
    expect(result.errors.join(' ')).toContain('reorganization');
  });
  it('marks a missing receipt unavailable rather than mismatched', async () => {
    const { service, rpc } = fixture();
    const original = rpc.getMockImplementation()!;
    rpc.mockImplementation(async (...args: any[]) =>
      args[0] === 'eth_getTransactionReceipt' ? null : original(...args),
    );
    const result = await service.verify('p');
    expect(result.status).toBe('unavailable');
    expect(result.transactions[0].status).toBe('unavailable');
  });
  it('does not infer a missing stored vote total', async () => {
    const { service } = fixture({ total_votes: null });
    expect((await service.verify('p')).status).toBe('unverified');
  });
  it('protects the internal endpoint with the server token', async () => {
    const { service } = fixture();
    const controller = new BlockchainVerificationController(service, config);
    expect(() => controller.verify('p', 'dao', 'Bearer attacker')).toThrow(
      'authentication',
    );
    await expect(
      controller.verify('p', 'dao', 'Bearer test-operator-token'),
    ).resolves.toHaveProperty('status', 'verified');
  });
});

describe('Verification HTTP integration with isolated SQL/RPC fixtures', () => {
  let app: NestFastifyApplication;
  beforeAll(async () => {
    const { service } = fixture();
    const module = await Test.createTestingModule({
      controllers: [BlockchainVerificationController],
      providers: [
        { provide: BlockchainVerificationService, useValue: service },
        { provide: ConfigService, useValue: config },
      ],
    }).compile();
    app = module.createNestApplication<NestFastifyApplication>(
      new FastifyAdapter(),
      { logger: false },
    );
    await app.init();
    await app.getHttpAdapter().getInstance().ready();
  });
  afterAll(async () => {
    await app.close();
  });
  it.each([
    [undefined, 'dao', 401],
    ['Bearer test-operator-token', 'other', 403],
    ['Bearer test-operator-token', 'dao', 200],
  ])(
    'enforces server token and DAO scope',
    async (authorization, dao, status) => {
      const result = await app.inject({
        method: 'GET',
        url: `/ai/internal/proposals/p/verification?dao_id=${dao}`,
        headers: authorization ? { authorization } : {},
      });
      expect(result.statusCode).toBe(status);
      if (status === 200)
        expect(JSON.parse(result.body)).toMatchObject({
          status: 'verified',
          indexer_checkpoint: { status: 'current' },
        });
    },
  );
});

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Interface, toBeHex, zeroPadValue, type JsonFragment } from 'ethers';
import { Web3RPCClient } from '@cyberchain/smart-contract-wrapper';
import {
  CYBER_DAO_GOVERNANCE_READ_ABI,
  CYBER_DAO_GOVERNANCE_WRITE_ABI,
} from '@dao-platform/blockchain-cyberchain';
import { PostgresService } from '../database/postgres.service';
import { ProposalStatus } from '@dao-platform/domain';

type ContractState = 'Pending' | 'Active' | 'Closed' | 'Cancelled';
export const DATABASE_STATE_MAP = {
  DRAFT: null,
  PENDING: null,
  PENDING_ON_CHAIN: null,
  FAILED: null,
  ACTIVE: 'Active',
  VOTING_OPEN: 'Active',
  VOTING_CLOSED: 'Closed',
  CLOSED: 'Closed',
  EXECUTED: null,
  FINALIZED: 'Closed',
  CANCELLED: 'Cancelled',
} as const satisfies Record<
  ProposalStatus | 'PENDING' | 'FINALIZED' | 'VOTING_OPEN',
  ContractState | null
>;

interface IndexerCheckpoint {
  indexer_name: string;
  indexer_version: string;
  status:
    'current' | 'lagging' | 'ahead' | 'missing' | 'invalid' | 'unavailable';
  processed_block_number?: string;
  processed_block_hash?: string | null;
  lag_blocks?: string;
  updated_at?: string;
  reason: string;
}

export type VerificationStatus =
  'verified' | 'mismatched' | 'unavailable' | 'unverified';
export interface Comparison {
  field: string;
  status: VerificationStatus;
  database: unknown;
  blockchain: unknown;
  reason?: string;
}
export interface VerificationReport {
  status: VerificationStatus;
  dao_id: string;
  proposal_id: string;
  on_chain_id: string | null;
  chain_id: string;
  contract: string;
  block_number?: string;
  block_hash?: string;
  indexer_checkpoint?: IndexerCheckpoint;
  observed_at: string;
  proposal?: Record<string, unknown>;
  voting_status?: string;
  vote_counts?: string[];
  comparisons: Comparison[];
  events: Array<Record<string, unknown>>;
  transactions: Array<Record<string, unknown>>;
  errors: string[];
  scope: string;
  duration_ms?: number;
}
const names = [
  'ProposalCreated',
  'MemberAssigned',
  'MemberUnassigned',
  'VoteCast',
  'ProposalCancelled',
  'ProposalFinalized',
];

@Injectable()
export class BlockchainVerificationService {
  private readonly abi = new Interface([
    ...(CYBER_DAO_GOVERNANCE_WRITE_ABI as unknown as JsonFragment[]),
    ...CYBER_DAO_GOVERNANCE_READ_ABI,
  ]);
  constructor(
    private readonly postgres: PostgresService,
    private readonly config: ConfigService,
  ) {}

  // Uses the platform's existing RPC client, URL and contract ABI. No caller can
  // choose an RPC method, URL, contract, block range or arbitrary transaction.
  protected rpc(method: string, params: unknown[]): Promise<any> {
    return Web3RPCClient.getInstance().rpcRequest(method, params, {
      rpcURL: this.config.getOrThrow<string>('CYBERCHAIN_RPC_URL'),
      timeout: 15_000,
    });
  }

  async verify(id: string, daoId?: string): Promise<VerificationReport> {
    const started = performance.now();
    const db = this.postgres.database;
    const p = await db
      .selectFrom('proposals')
      .selectAll()
      .where('id', '=', id)
      .executeTakeFirst();
    if (!p) throw new NotFoundException('Proposal not found.');
    if (daoId && daoId !== p.dao_id)
      throw new ForbiddenException('Proposal is outside the selected DAO.');
    const report: VerificationReport = {
      status: 'unverified',
      dao_id: p.dao_id,
      proposal_id: p.id,
      on_chain_id: p.on_chain_id?.toString() ?? null,
      chain_id: String(p.chain_id),
      contract: p.contract_address,
      observed_at: new Date().toISOString(),
      comparisons: [],
      events: [],
      transactions: [],
      errors: [],
      scope:
        'Pinned block; selected proposal only. Title, purpose and document contents are off-chain and remain unverified.',
    };
    const compare = (
      field: string,
      local: unknown,
      live: unknown,
      reason?: string,
    ) =>
      report.comparisons.push({
        field,
        database: local ?? null,
        blockchain: live ?? null,
        status:
          local == null || live == null
            ? 'unverified'
            : String(local).toLowerCase() === String(live).toLowerCase()
              ? 'verified'
              : 'mismatched',
        ...(reason
          ? { reason }
          : local == null
            ? {
                reason:
                  'Database value is missing; the on-chain value was read successfully.',
              }
            : {}),
      });
    if (p.on_chain_id == null) {
      report.errors.push('This proposal has no on-chain identifier.');
      return report;
    }
    if (
      String(p.chain_id) !== this.config.get<string>('CYBERCHAIN_CHAIN_ID') ||
      p.contract_address.toLowerCase() !==
        this.config.get<string>('GOVERNANCE_CONTRACT_ADDRESS')?.toLowerCase()
    ) {
      report.errors.push(
        'Proposal deployment does not match the configured deployment.',
      );
      return report;
    }
    try {
      const actualChain = BigInt(await this.rpc('eth_chainId', [])).toString();
      if (actualChain !== String(p.chain_id)) {
        report.status = 'mismatched';
        compare('chain_id', String(p.chain_id), actualChain);
        return report;
      }
      const block = await this.rpc('eth_blockNumber', []);
      const snapshot = await this.rpc('eth_getBlockByNumber', [block, false]);
      if (
        !snapshot?.hash ||
        snapshot.number == null ||
        BigInt(snapshot.number) !== BigInt(block)
      )
        throw new Error('Snapshot block unavailable or inconsistent');
      report.block_number = BigInt(block).toString();
      report.block_hash = snapshot.hash;
      const checkpoint: IndexerCheckpoint = {
        indexer_name: 'governance-full',
        indexer_version: '1',
        status: 'missing',
        reason: 'No checkpoint for this chain, contract and indexer version.',
      };
      report.indexer_checkpoint = checkpoint;
      try {
        const row = await db
          .selectFrom('indexer_checkpoints')
          .selectAll()
          .where('chain_id', '=', p.chain_id)
          .where('contract_address', '=', p.contract_address)
          .where('indexer_name', '=', 'governance-full')
          .where('indexer_version', '=', '1')
          .executeTakeFirst();
        if (row) {
          const height = String(row.processed_block_number);
          checkpoint.status = 'invalid';
          checkpoint.reason = 'Invalid checkpoint height or hash.';
          if (/^(0|[1-9][0-9]*)$/.test(height)) {
            checkpoint.processed_block_number = height;
            if (row.updated_at != null) {
              const updated = new Date(row.updated_at);
              if (Number.isFinite(updated.getTime()))
                checkpoint.updated_at = updated.toISOString();
            }
            checkpoint.processed_block_hash = row.processed_block_hash;
            const delta = BigInt(block) - BigInt(height);
            checkpoint.lag_blocks = delta.toString();
            checkpoint.status =
              delta < 0n ? 'ahead' : delta > 0n ? 'lagging' : 'current';
            checkpoint.reason =
              delta < 0n
                ? 'SQL is newer than the pinned block; historical SQL is unavailable.'
                : delta > 0n
                  ? 'Indexer has not covered the pinned block.'
                  : 'Indexer height equals the pinned block.';
            if (row.processed_block_hash != null) {
              const anchor =
                delta === 0n
                  ? snapshot
                  : await this.rpc('eth_getBlockByNumber', [
                      toBeHex(BigInt(height)),
                      false,
                    ]);
              if (
                !/^0x[0-9a-f]{64}$/i.test(row.processed_block_hash) ||
                !anchor?.hash ||
                anchor.number == null ||
                BigInt(anchor.number) !== BigInt(height) ||
                anchor.hash.toLowerCase() !==
                  row.processed_block_hash.toLowerCase()
              ) {
                checkpoint.status = 'invalid';
                checkpoint.reason =
                  'Checkpoint hash is invalid or differs from the canonical chain.';
              }
            } else
              checkpoint.reason +=
                ' Checkpoint hash not recorded; canonical anchoring unavailable.';
          }
        }
      } catch {
        checkpoint.status = 'unavailable';
        checkpoint.reason = 'Checkpoint query or canonical block read failed.';
      }
      report.comparisons.push({
        field: 'indexer_checkpoint',
        database: checkpoint,
        blockchain: report.block_number,
        status: checkpoint.status === 'current' ? 'verified' : 'unverified',
        reason: checkpoint.reason,
      });
      const call = async (name: string, args: unknown[]) =>
        this.abi.decodeFunctionResult(
          name,
          await this.rpc('eth_call', [
            {
              to: p.contract_address,
              data: this.abi.encodeFunctionData(name, args),
            },
            block,
          ]),
        );
      const [proposalResult, stateResult] = await Promise.all([
        call('getProposal', [p.on_chain_id]),
        call('proposalState', [p.on_chain_id]),
      ]);
      const value = proposalResult[0];
      report.proposal = Object.fromEntries(
        [
          'metadataHash',
          'metadataURI',
          'startsAt',
          'endsAt',
          'optionCount',
          'winningOption',
          'assignedMemberCount',
          'voteCount',
          'proposalType',
          'cancelled',
          'finalized',
          'tied',
        ].map((key, i) => [
          key,
          typeof value[i] === 'bigint' ? value[i].toString() : value[i],
        ]),
      );
      const live = report.proposal;
      const state = ['Pending', 'Active', 'Closed', 'Cancelled'][
        Number(stateResult[0])
      ];
      if (
        !state ||
        Number(live.optionCount) < 2 ||
        Number(live.optionCount) > 10
      )
        throw new Error('Unexpected contract response');
      report.voting_status = state;
      const key = p.status as keyof typeof DATABASE_STATE_MAP;
      let localState: ContractState | null = Object.hasOwn(
        DATABASE_STATE_MAP,
        key,
      )
        ? DATABASE_STATE_MAP[key]
        : null;
      // Publication persists ACTIVE even for scheduled proposals. Derive the
      // temporal state using SQL times and the pinned chain clock.
      if (key === 'ACTIVE' || key === 'VOTING_OPEN') {
        const now =
          snapshot.timestamp == null ? NaN : Number(BigInt(snapshot.timestamp));
        const start = new Date(p.starts_at).getTime() / 1000;
        const end = new Date(p.ends_at).getTime() / 1000;
        localState =
          Number.isFinite(now) &&
          Number.isFinite(start) &&
          Number.isFinite(end) &&
          end > start
            ? now < start
              ? 'Pending'
              : now < end
                ? 'Active'
                : 'Closed'
            : null;
      }
      if (localState == null)
        report.comparisons.push({
          field: 'voting_status',
          database: p.status,
          blockchain: state,
          status: 'unverified',
          reason:
            'Unknown, unsupported or unpublished SQL status, or missing pinned clock; no contract state inferred.',
        });
      else compare('voting_status', localState, state);
      compare('metadata_hash', p.metadata_hash, live.metadataHash);
      compare('metadata_uri', p.metadata_uri, live.metadataURI);
      compare(
        'starts_at',
        Math.floor(new Date(p.starts_at).getTime() / 1000).toString(),
        live.startsAt,
      );
      compare(
        'ends_at',
        Math.floor(new Date(p.ends_at).getTime() / 1000).toString(),
        live.endsAt,
      );
      compare('finalized', p.finalized_at ? true : false, live.finalized);
      if (live.finalized) {
        compare('winning_option', p.winning_option, live.winningOption);
        compare('tied', p.tied, live.tied);
      }
      report.vote_counts = await Promise.all(
        Array.from({ length: Number(live.optionCount) }, async (_, i) =>
          String((await call('optionVoteCount', [p.on_chain_id, i]))[0]),
        ),
      );
      const votes = await db
        .selectFrom('votes')
        .selectAll()
        .where('proposal_id', '=', id)
        .execute();
      compare('public.votes.count', votes.length, live.voteCount);
      const assignments = await db
        .selectFrom('proposal_assignments')
        .selectAll()
        .where('proposal_id', '=', id)
        .where('assigned', '=', true)
        .execute();
      compare(
        'public.proposal_assignments.count',
        assignments.length,
        live.assignedMemberCount,
      );
      compare(
        'public.proposals.total_votes',
        p.total_votes?.toString(),
        live.voteCount,
      );
      report.vote_counts.forEach((count, index) =>
        compare(
          `option_${index}_vote_count`,
          votes.filter((v) => v.option_index === index).length,
          count,
        ),
      );
      const stored = await db
        .selectFrom('governance_events')
        .selectAll()
        .where('chain_id', '=', p.chain_id)
        .where('contract_address', '=', p.contract_address)
        .where('proposal_id', '=', p.on_chain_id)
        .where('canonical', '=', true)
        .execute();
      const creation = stored.find((e) => e.event_name === 'ProposalCreated');
      const from = creation
        ? BigInt(String(creation.block_number))
        : BigInt(this.config.get<string>('GOVERNANCE_DEPLOYMENT_BLOCK') ?? '0');
      let logs: any[] | null = null;
      try {
        const topics = [
          names.map((name) => this.abi.getEvent(name)!.topicHash),
          zeroPadValue(toBeHex(BigInt(p.on_chain_id)), 32),
        ];
        const ranges: Array<[bigint, bigint]> = [];
        for (
          let start = from;
          start <= BigInt(block) && ranges.length < 2000;
          start += 1000n
        )
          ranges.push([
            start,
            start + 999n < BigInt(block) ? start + 999n : BigInt(block),
          ]);
        const fullRange =
          !ranges.length || ranges[ranges.length - 1][1] === BigInt(block);
        let next = 0;
        const found: any[] = [];
        const deadline = performance.now() + 75_000;
        await Promise.all(
          Array.from({ length: Math.min(8, ranges.length) }, async () => {
            while (next < ranges.length) {
              if (performance.now() > deadline)
                throw new Error('Event scan deadline exceeded');
              const [start, end] = ranges[next++];
              const batch = await this.rpc('eth_getLogs', [
                {
                  address: p.contract_address,
                  fromBlock: '0x' + start.toString(16),
                  toBlock: '0x' + end.toString(16),
                  topics,
                },
              ]);
              if (!Array.isArray(batch))
                throw new Error('Invalid log response');
              found.push(...batch);
              if (found.length > 10_000)
                throw new Error('Event limit exceeded');
            }
          }),
        );
        logs = [
          ...new Map(
            found.map((log) => [`${log.transactionHash}:${log.logIndex}`, log]),
          ).values(),
        ];
        if (!Array.isArray(logs) || logs.length > 10_000)
          throw new Error('Event limit exceeded');
        report.events = logs.map((log) => {
          const decoded = this.abi.parseLog(log)!;
          const args = Object.fromEntries(
            decoded.fragment.inputs.map((input, i) => [
              input.name,
              typeof decoded.args[i] === 'bigint'
                ? decoded.args[i].toString()
                : decoded.args[i],
            ]),
          );
          return {
            name: decoded.name,
            args,
            transaction_hash: log.transactionHash,
            log_index: BigInt(log.logIndex).toString(),
            block_number: BigInt(log.blockNumber).toString(),
            block_hash: log.blockHash,
            status: 'verified',
          };
        });
        const key = (hash: string, index: string) =>
          `${hash.toLowerCase()}:${index}`;
        const eventMap = new Map(
          report.events.map((e) => [
            key(String(e.transaction_hash), String(e.log_index)),
            e,
          ]),
        );
        const storedKeys = new Set(
          stored.map((row) => key(row.transaction_hash, String(row.log_index))),
        );
        const scannedThrough = ranges.at(-1)?.[1];
        for (const row of stored) {
          const event = eventMap.get(
            key(row.transaction_hash, String(row.log_index)),
          );
          const same =
            !!event &&
            event.name === row.event_name &&
            event.block_hash === row.block_hash &&
            Object.entries(row.event_args as Record<string, unknown>).every(
              ([k, v]) =>
                String(
                  (event.args as Record<string, unknown>)[k],
                ).toLowerCase() === String(v).toLowerCase(),
            );
          report.comparisons.push({
            field: `governance_event:${row.evidence_id}`,
            database: {
              name: row.event_name,
              transaction_hash: row.transaction_hash,
              log_index: String(row.log_index),
              block_number: String(row.block_number),
              block_hash: row.block_hash,
              args: row.event_args,
            },
            blockchain: event ?? null,
            status: same
              ? 'verified'
              : event ||
                  (scannedThrough !== undefined &&
                    BigInt(String(row.block_number)) >= from &&
                    BigInt(String(row.block_number)) <= scannedThrough)
                ? 'mismatched'
                : 'unverified',
          });
        }
        for (const event of report.events) {
          const eventKey = key(
            String(event.transaction_hash),
            String(event.log_index),
          );
          if (!storedKeys.has(eventKey)) {
            report.comparisons.push({
              field: `governance_event:${eventKey}`,
              database: null,
              blockchain: event,
              status:
                (checkpoint.status === 'current' ||
                  checkpoint.status === 'lagging') &&
                BigInt(String(event.block_number)) <=
                  BigInt(checkpoint.processed_block_number!)
                  ? 'mismatched'
                  : 'unverified',
              reason:
                'Chain event has no indexed counterpart. A discrepancy requires validated checkpoint coverage.',
            });
          }
        }
        const verifiedCreation = report.events.some(
          (e) => e.name === 'ProposalCreated',
        );
        if (
          fullRange &&
          verifiedCreation &&
          (checkpoint.status === 'current' || checkpoint.status === 'lagging')
        ) {
          const covered =
            BigInt(checkpoint.processed_block_number!) < BigInt(block)
              ? BigInt(checkpoint.processed_block_number!)
              : BigInt(block);
          compare(
            'governance_events.count',
            stored.filter(
              (e) =>
                BigInt(String(e.block_number)) >= from &&
                BigInt(String(e.block_number)) <= covered,
            ).length,
            report.events.filter(
              (e) => BigInt(String(e.block_number)) <= covered,
            ).length,
            'Only the fully scanned, checkpoint-covered interval is compared.',
          );
          if (checkpoint.status === 'lagging') {
            const pending = report.events.filter(
              (e) =>
                BigInt(String(e.block_number)) > covered &&
                !storedKeys.has(
                  key(String(e.transaction_hash), String(e.log_index)),
                ),
            );
            const deltas: Record<string, number> = {
              'public.votes.count': pending.filter((e) => e.name === 'VoteCast')
                .length,
              'public.proposals.total_votes': pending.filter(
                (e) => e.name === 'VoteCast',
              ).length,
              'public.proposal_assignments.count':
                pending.filter((e) => e.name === 'MemberAssigned').length -
                pending.filter((e) => e.name === 'MemberUnassigned').length,
            };
            report.vote_counts.forEach((_, i) => {
              deltas[`option_${i}_vote_count`] = pending.filter(
                (e) =>
                  e.name === 'VoteCast' &&
                  String((e.args as Record<string, unknown>).optionIndex) ===
                    String(i),
              ).length;
            });
            for (const comparison of report.comparisons) {
              const delta = deltas[comparison.field];
              // Do not blanket suppress mismatches when an indexer lags. Only
              // an exact, independently observed event delta explains a count.
              if (
                comparison.status === 'mismatched' &&
                delta != null &&
                delta !== 0 &&
                BigInt(String(comparison.blockchain)) -
                  BigInt(String(comparison.database)) ===
                  BigInt(delta)
              ) {
                comparison.status = 'unverified';
                comparison.reason =
                  'Exact count difference explained by canonical events after the indexer checkpoint; indexing lag, not proven divergence.';
              }
            }
          }
        } else
          report.comparisons.push({
            field: 'governance_events.historical_coverage',
            database: stored.length,
            blockchain: report.events.length,
            status: 'unverified',
            reason:
              'Historical scan incomplete, creation not verified, or checkpoint missing/invalid/ahead; maximum 2,000,000 blocks per request.',
          });
        for (const vote of votes) {
          const event = report.events.find(
            (e) =>
              e.name === 'VoteCast' &&
              e.transaction_hash === vote.transaction_hash &&
              String((e.args as any).voter).toLowerCase() ===
                vote.voter_address.toLowerCase(),
          );
          const matches =
            !!event &&
            String((event.args as any).optionIndex) ===
              String(vote.option_index) &&
            event.block_hash === vote.block_hash;
          report.comparisons.push({
            field: `vote:${vote.voter_address}`,
            database: {
              option: vote.option_index,
              transaction_hash: vote.transaction_hash,
            },
            blockchain: event ?? null,
            status: matches
              ? 'verified'
              : event ||
                  (scannedThrough !== undefined &&
                    BigInt(String(vote.block_number)) >= from &&
                    BigInt(String(vote.block_number)) <= scannedThrough)
                ? 'mismatched'
                : 'unverified',
          });
        }
      } catch {
        report.errors.push('Governance logs could not be completely verified.');
        report.comparisons.push({
          field: 'governance_events',
          database: stored.length,
          blockchain: null,
          status: 'unavailable',
        });
      }
      const hashes = [
        ...new Set([
          ...stored.map((e) => e.transaction_hash),
          ...votes.map((v) => v.transaction_hash),
          ...report.events.map((e) => String(e.transaction_hash)),
        ]),
      ];
      if (hashes.length > 200)
        report.errors.push(
          'Transaction verification is limited to 200 proposal transactions. Remaining transactions are unverified.',
        );
      for (const hash of hashes.slice(0, 200)) {
        try {
          const [receipt, transaction] = await Promise.all([
            this.rpc('eth_getTransactionReceipt', [hash]),
            this.rpc('eth_getTransactionByHash', [hash]),
          ]);
          if (!receipt || !transaction) {
            report.transactions.push({ hash, status: 'unavailable' });
            report.errors.push(
              'A proposal transaction or receipt is unavailable.',
            );
            continue;
          }
          const matchingEvents = report.events.filter(
            (e) => e.transaction_hash === hash,
          );
          const ok =
            receipt &&
            transaction &&
            BigInt(receipt.status) === 1n &&
            String(receipt.to).toLowerCase() ===
              p.contract_address.toLowerCase() &&
            BigInt(receipt.blockNumber) <= BigInt(block) &&
            matchingEvents.every((e) => e.block_hash === receipt.blockHash);
          report.transactions.push({
            hash,
            block_number: receipt?.blockNumber
              ? BigInt(receipt.blockNumber).toString()
              : null,
            block_hash: receipt?.blockHash ?? null,
            from: transaction?.from ?? null,
            to: transaction?.to ?? null,
            status: ok ? 'verified' : 'mismatched',
          });
        } catch {
          report.transactions.push({ hash, status: 'unavailable' });
          report.errors.push('A proposal transaction receipt is unavailable.');
        }
      }
      const canonical = await this.rpc('eth_getBlockByNumber', [block, false]);
      if (canonical?.hash !== snapshot.hash) {
        report.errors.push(
          'Snapshot block changed during verification (possible chain reorganization).',
        );
        report.comparisons.forEach((c) => {
          c.status = 'unverified';
        });
        report.events.forEach((e) => {
          e.status = 'unverified';
        });
        report.transactions.forEach((t) => {
          t.status = 'unverified';
        });
        report.status = 'unverified';
      } else if (
        report.comparisons.some((c) => c.status === 'mismatched') ||
        report.transactions.some((t) => t.status === 'mismatched')
      )
        report.status = 'mismatched';
      else if (report.errors.length || !logs) report.status = 'unavailable';
      else if (report.comparisons.some((c) => c.status === 'unverified'))
        report.status = 'unverified';
      else report.status = 'verified';
    } catch {
      report.status = 'unavailable';
      report.errors.push(
        'RPC or contract read unavailable. No on-chain verification is claimed.',
      );
    }
    report.duration_ms = performance.now() - started;
    return report;
  }
}
